beforeExample:
import junit.framework.TestCase;
import org.eclipse.jface.text.TextSelection;
import org.eclipse.jface.text.ITextSelection;

public class ExampleTest extends TestCase {
    public void testAssertion() {
        int x = 5;
        int y = 5;
        assertTrue(x == y);
        assertTrue(0 == x); // Also covers constant on left

        ITextSelection selection = new TextSelection(0, 0); // Mock
        assertTrue(selection.getOffset() == 0);
        int actualValue = someMethod();
        assertTrue(actualValue == 10);
    }

    private int someMethod() { return 0; }
}

afterExample:
import junit.framework.TestCase;
import org.eclipse.jface.text.TextSelection;
import org.eclipse.jface.text.ITextSelection;

public class ExampleTest extends TestCase {
    public void testAssertion() {
        int x = 5;
        int y = 5;
        assertEquals(y, x);
        assertEquals(0, x);

        ITextSelection selection = new TextSelection(0, 0); // Mock
        assertEquals(0, selection.getOffset());
        int actualValue = someMethod();
        assertEquals(10, actualValue);
    }

    private int someMethod() { return 0; }
}

negativeExample:
import junit.framework.TestCase;

public class ExampleTest extends TestCase {
    public void testOtherAssertions() {
        boolean condition = true;
        // Not an equality check
        assertTrue(condition);
        assertTrue(5 > 3);
        // Not integer types
        String s1 = "hello";
        String s2 = "world";
        assertTrue(s1.equals(s2));
        // Has a message argument (different overload)
        assertTrue("Message", 5 == 5);
        // Already assertEquals
        assertEquals(5, 5);
        // Long comparison
        long l1 = 1L, l2 = 2L;
        assertTrue(l1 == l2);
    }
}
